script:
(function () {
  'use strict';
  // Compounding frequency, fees and taxes on a single investment.
  // Effective yearly growth (APY) of nominal rate r compounded n times a year: (1 + r/n)^n - 1;
  // continuous compounding: e^r - 1. Ending value before costs = P x (1 + APY)^years.
  // Costs are applied once a year: the fee is a % of the year-end balance, so the growth factor
  // after fees is (1 + APY) x (1 - fee); tax is then charged on that year's positive earnings and
  // paid from the account, so net yearly return g = ((1 + APY)(1 - fee) - 1) x (1 - tax) when
  // positive (no tax and no credit on a loss). Ending value after costs = P x (1 + g)^years.
  // CHECKS (Node, scratch tests/cy.test.js): $10,000 at 6% for 10 years = $17,908.48 annually,
  // $18,061.11 semiannually, $18,140.18 quarterly, $18,193.97 monthly, $18,220.29 daily (365)
  // and $18,221.19 continuously (10,000 x e^0.6); APY 6% monthly = 6.1678%, continuous 6.1837%;
  // 0% fee and 0% tax leave the ending value unchanged; a 0.5% fee at 6% annual compounding
  // gives 10,000 x (1.06 x 0.995)^10 = $17,032.93; 0% rate gives $10,000 at every frequency.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var FREQS = [
    { n: 1, label: 'Annually' }, { n: 2, label: 'Semiannually' }, { n: 4, label: 'Quarterly' },
    { n: 12, label: 'Monthly' }, { n: 365, label: 'Daily' }, { n: 0, label: 'Continuously' }
  ];
  var IDS = ['cyNet', 'cyGross', 'cyNetRate', 'cyApy', 'cyFees', 'cyTaxes', 'cyPeriodic'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x, d) { return (x * 100).toFixed(d) + '%'; }

  function apy(r, n) { return n === 0 ? Math.exp(r) - 1 : Math.pow(1 + r / n, n) - 1; }
  function afterFee(y, fee) { return (1 + y) * (1 - fee) - 1; }
  function afterTax(g, tax) { return g > 0 ? g * (1 - tax) : g; }

  function project(P, r, n, years, fee, tax) {
    var y = apy(r, n), gf = afterFee(y, fee), gt = afterTax(gf, tax), rows = [];
    for (var t = 1; t <= years; t++) {
      rows.push({ year: t, gross: P * Math.pow(1 + y, t), fees: P * Math.pow(1 + gf, t), net: P * Math.pow(1 + gt, t) });
    }
    var last = rows[rows.length - 1];
    return { apy: y, netRate: gt, gross: last.gross, fees: last.fees, net: last.net, rows: rows };
  }

  function update() {
    var P = num('cyAmount'), rate = num('cyRate'), years = Math.round(num('cyYears')),
        n = parseInt(document.getElementById('cyCompound').value, 10),
        fee = num('cyFee'), tax = num('cyTax');
    var error = document.getElementById('cyError');
    var bad = [P, rate, years, fee, tax].some(isNaN) || isNaN(n) || P < 0 || rate < 0 || rate > 50 ||
              years < 1 || years > 100 || fee < 0 || fee > 10 || tax < 0 || tax > 60;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an amount of $0 or more, a rate from 0 to 50%, 1 to 100 years, a fee from 0 to 10% and a tax rate from 0 to 60%.';
      IDS.forEach(function (id) { set(id, '–'); });
      set('cySummary', '');
      document.getElementById('cyFreqTable').innerHTML = '';
      document.getElementById('cySchedule').innerHTML = '';
      return;
    }
    var r = rate / 100, f = fee / 100, t = tax / 100;
    var res = project(P, r, n, years, f, t);
    set('cyNet', money.format(res.net));
    set('cyGross', money.format(res.gross));
    set('cyNetRate', pct(res.netRate, 2));
    set('cyApy', pct(res.apy, 4));
    set('cyFees', money.format(res.gross - res.fees));
    set('cyTaxes', money.format(res.fees - res.net));
    set('cyPeriodic', n === 0 ? 'Continuous' : pct(r / n, 4));
    set('cySummary', 'Fees and taxes take ' + money.format(res.gross - res.net) + ' of the ' +
        money.format(res.gross - P) + ' your money would earn before costs over ' + years + (years === 1 ? ' year.' : ' years.'));

    var base = P * Math.pow(1 + apy(r, 1), years);
    var tbody = document.getElementById('cyFreqTable');
    tbody.textContent = '';
    FREQS.forEach(function (fq) {
      var y = apy(r, fq.n), end = P * Math.pow(1 + y, years), tr = document.createElement('tr');
      var cells = [fq.label, pct(y, 4), money.format(end), money.format(end - P), money.format(end - base)];
      cells.forEach(function (text, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = text;
        if (i === 0 && fq.n === n) {
          var b = document.createElement('span');
          b.className = 'badge badge-sky ml-2';
          b.textContent = 'Selected';
          td.appendChild(b);
        }
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });

    document.getElementById('cySchedule').innerHTML = res.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.gross) + '</td><td>' + money.format(row.fees) +
             '</td><td>' + money.format(row.net) + '</td><td>' + money.format(row.gross - row.net) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cyForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
